// Reads the golden frames generated by the Go server (protocol/fixtures), as
// apple/RAKit/Tests/RAKitTests/FixtureTests.swift does.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import {
  aspectRatio,
  contextFraction,
  effortsForModel,
  imageIdLinkedBy,
  installable,
  modelName,
  parseDate,
  usable,
  type Diff,
  type Event,
  type FSListing,
  type HarnessInfo,
  type PairResult,
  type ServerInfo,
  type SlashCommand,
  type ServerSettings,
  type ServerTask,
  type Session,
  type TerminalMessage,
  type UpdateInfo,
} from "./models";

const dir = join(import.meta.dirname, "../../../protocol/fixtures");
const load = (name: string) => JSON.parse(readFileSync(join(dir, name), "utf8"));

describe("fixtures", () => {
  it("session command catalog", () => {
    const commands: SlashCommand[] = load("response_session_commands.json").result.commands;
    expect(commands.map((c) => c.name)).toEqual(["compact", "skill:prototype"]);
    expect(commands[1]).toEqual({ name: "skill:prototype", description: "Prototype to answer a design question", kind: "skill", scope: "user" });
    expect(commands[0].kind).toBeUndefined();
  });
  it("session events", () => {
    const n = load("notification_events_session.json");
    expect(n.method).toBe("events");
    const events: Event[] = n.params.events;
    expect(events).toHaveLength(14);
    const session = events[0].session!;
    expect(session.status).toBe("awaiting_approval");
    expect(session.draft?.images).toHaveLength(1);
    expect(session.workspace.kind).toBe("worktree");
    expect(session.workspace.agentPath).toBe("/w/s1/.claude/worktrees/fix");
    expect(session.forkedFrom).toEqual({ sessionId: "s0", turn: 3 });
    expect(events[1].turn?.usage?.costUsd).toBe(0.0123);
    const items = events.flatMap((e) => (e.item ? [e.item] : []));
    expect(items).toHaveLength(11);
    expect(items.map((i) => i.kind)).toEqual([
      "user_message",
      "reasoning",
      "tool_call",
      "assistant_message",
      "approval",
      "approval",
      "approval",
      "plan",
      "notice",
      "error",
      "assistant_message",
    ]);
    expect(items[0].images?.[0].mimeType).toBe("image/png");
    expect(aspectRatio(items[0].images![0])).toBe(1170 / 2532);
    expect(items[2].images?.[0].width).toBeUndefined(); // WebP: no dimensions
    expect(aspectRatio(items[2].images![0])).toBeUndefined();
    expect((items[2].tool?.input as Record<string, unknown>).command).toBe("go test ./...");
    expect(items[2].tool?.exitCode).toBe(0);
    // A reply links to the images it shows as rad-image:<id>.
    const shown = items[3].images![0];
    expect(items[3].text?.endsWith(`![Screenshot](rad-image:${shown.id})`)).toBe(true);
    expect(imageIdLinkedBy(`rad-image:${shown.id}`)).toBe(shown.id);
    expect(imageIdLinkedBy("https://example.com/a.png")).toBeUndefined();
    expect(items[4].approval?.options?.map((o) => o.kind)).toEqual(["allow_once", "allow_session", "deny"]);
    expect(items[5].approval?.special).toBe("question");
    expect(items[5].approval?.decision?.answers?.["Which DB?"]).toBe("SQLite");
    expect(items[5].approval?.questions?.map((q) => q.optionsOnly)).toEqual([undefined, true]);
    expect(items[6].approval?.special).toBe("plan");
    expect(items[7].plan?.entries).toHaveLength(2);
    expect(items[10].parentItemId).toBe("i3");
    // Unknown event types come through, for the stores to skip.
    expect(events[events.length - 1].type).toBe("future.event");
    expect(Number.isNaN(parseDate(items[0].createdAt))).toBe(false);
  });

  it("index events", () => {
    const events: Event[] = load("notification_events_index.json").params.events;
    expect(events.map((e) => e.type)).toEqual(["project.upserted", "session.upserted", "project.removed"]);
    expect(events[0].project?.isGitRepo).toBe(true);
    expect(events[1].session?.draft?.text).toBe("Then update the changelog");
    expect(events[2].id).toBe("p0");
  });

  it("responses", () => {
    const harnesses: HarnessInfo[] = load("response_harness_list.json").result.harnesses;
    expect(harnesses).toHaveLength(2);
    expect(usable(harnesses[0])).toBe(true);
    expect(usable(harnesses[1])).toBe(false);
    expect(harnesses[1].hint).toBeTruthy();
    // A model's own efforts replace the harness's; others get the default model's.
    const claude = harnesses[0];
    expect(effortsForModel(claude, "sonnet").map((e) => e.id)).toEqual(["low", "high"]);
    expect(effortsForModel(claude, undefined).map((e) => e.id)).toEqual(["low", "medium", "high"]);
    expect(effortsForModel(harnesses[1], undefined)).toEqual([]);
    expect(claude.commands?.map((c) => "/" + c.name)).toEqual(["/compact"]);
    expect(claude.commands?.[0].description).toBeTruthy();
    expect(harnesses[1].commands).toBeUndefined();
    // What the server settings offer for each agent; older servers leave them out.
    expect(claude.caps).toMatchObject({ update: true, login: true, oneShot: true, steer: true });
    expect(harnesses[1].caps.update).toBeUndefined();
    expect(harnesses[1].caps.login).toBeUndefined();
    expect(harnesses[1].caps.oneShot).toBeUndefined();
    expect(harnesses[1].caps.steer).toBeUndefined();

    const diff: Diff = load("response_diff.json").result;
    expect(diff.files.map((f) => f.status)).toEqual(["modified", "renamed", "added"]);
    expect(diff.files[2].binary).toBe(true);

    const fs: FSListing = load("response_fs_list.json").result;
    expect(fs.entries).toHaveLength(2);

    expect(load("response_error.json").error.code).toBe("conflict");

    const s: Session = load("response_session.json").result;
    expect(s.title).toBe("Fix the tests");
    expect(s.unread).toBe(true);
    expect(s.draft?.text).toBe("Then update the changelog");
    expect(s.draft?.images?.map((i) => [i.mimeType, i.width, i.height, i.size])).toEqual([["image/jpeg", 800, 600, 65536]]);
    expect(contextFraction(s.context)).toBe(0.26);
    expect(modelName(s, undefined)).toBe("Sonnet 5.5");
    expect(s.modelInfo?.effort).toBe("high");
    expect(s.effort).toBe("high");
    expect(s.backgroundTasks).toEqual([
      { id: "b1", kind: "command", description: "Watch the release run" },
      { id: "a1", kind: "agent", description: "Explore the protocol" },
    ]);

    const p: PairResult = load("http_pair_response.json");
    expect(p.token).toBe("0123abcd");

    const info: ServerInfo = load("response_server_info.json").result;
    expect(info.terminal).toBe(true);
    expect(info.drafts).toBe(true);
    expect(info.forks).toBe(true);
    expect(info.deviceId).toBe("dev1");
  });

  it("server management", () => {
    const settings: ServerSettings = load("response_server_settings.json").result;
    expect(settings.systemAgent).toEqual({ harness: "claude", model: "haiku", effort: "low" });

    const update: UpdateInfo = load("response_check_update.json").result;
    expect(update).toMatchObject({ current: "0.11.0", latest: "0.12.0", available: true, via: "app" });
    expect(update.url).toMatch(/^https:\/\/github\.com\/.+\/v0\.12\.0$/);
    expect(update.busy).toEqual(["Fix the tests"]);
    expect(update.reason).toBeUndefined();
    expect(installable(update)).toBe(true);
    expect(installable({ ...update, via: undefined, reason: "rad dev is a development build, which doesn't update itself." })).toBe(false);

    const login: ServerTask = load("response_task.json").result;
    expect(login).toMatchObject({ id: "k1", kind: "login", harness: "claude", status: "running", input: true });
    expect(login.url).toBe("https://claude.com/cai/oauth/authorize?code=true");
    expect(login.output.split("\n")[0]).toBe("$ claude auth login");
    expect(Number.isNaN(parseDate(login.startedAt))).toBe(false);
    expect(login.endedAt).toBeUndefined();
    expect(login.version).toBeUndefined();

    const tasks: ServerTask[] = load("response_task_list.json").result.tasks;
    expect(tasks.map((t) => [t.kind, t.status])).toEqual([
      ["update_agent", "succeeded"],
      ["update_server", "failed"],
    ]);
    expect(tasks[0]).toMatchObject({ harness: "codex", version: "0.164.0" });
    expect(tasks[0].input).toBeUndefined();
    expect(tasks[1].harness).toBeUndefined();
    expect(tasks[1].error).toMatch(/checksum/);
    expect(parseDate(tasks[1].endedAt) - parseDate(tasks[1].startedAt)).toBe(5000);
  });

  it("terminal messages", () => {
    const a: TerminalMessage = load("terminal_attached.json");
    expect(a).toMatchObject({ type: "attached", reset: true, offset: 262130, cols: 80, rows: 24 });
    expect(a.id).toBeTruthy();
    // What a client sends matches the server's fixture.
    const sent: TerminalMessage = { type: "resize", cols: 120, rows: 40 };
    expect(load("terminal_resize.json")).toEqual(sent);
    expect((load("terminal_exit.json") as TerminalMessage).exitCode).toBe(129);
    expect(load("terminal_error.json")).toMatchObject({ type: "error", code: "gone" });
  });

  it("notifications", () => {
    expect(load("notification_synchronized.json").params).toEqual({ stream: "session:s1", seq: 14, reset: true });
    expect(load("notification_resync.json").params.stream).toBe("session:s1");
    expect(load("response_subscribe.json").result).toEqual({ stream: "session:s1", seq: 14 });
  });
});

describe("parseDate", () => {
  it("reads Go's times", () => {
    expect(parseDate("2026-10-09T01:50:59.955123456Z")).toBe(Date.UTC(2026, 9, 9, 1, 50, 59, 955));
    expect(parseDate("2026-10-09T01:50:59Z")).toBe(Date.UTC(2026, 9, 9, 1, 50, 59));
    expect(parseDate("2026-10-09T01:50:59.9+02:00")).toBe(Date.UTC(2026, 9, 8, 23, 50, 59, 900));
  });
});
